static int[] applyRangeAdds(int size, List<int[]> updates) {
    int[] diff = new int[size + 1];
    for (int[] update : updates) {
        int left = update[0];
        int right = update[1];
        int delta = update[2];
        diff[left] += delta;
        if (right + 1 < diff.length) diff[right + 1] -= delta;
    }

    int[] result = new int[size];
    int running = 0;
    for (int i = 0; i < size; i++) {
        running += diff[i];
        result[i] = running;
    }
    return result;
}

