static long fib(int n) {
    long[] memo = new long[n + 1];
    Arrays.fill(memo, -1L);
    return solve(n, memo);
}

private static long solve(int i, long[] memo) {
    if (i <= 1) return i;
    if (memo[i] != -1L) return memo[i];
    memo[i] = solve(i - 1, memo) + solve(i - 2, memo);
    return memo[i];
}

