static long fibTab(int n) {
    if (n <= 1) return n;
    long prev = 0L;
    long curr = 1L;
    for (int i = 0; i < n - 1; i++) {
        long next = prev + curr;
        prev = curr;
        curr = next;
    }
    return curr;
}

