static int maxNonAdjacentSum(int[] values) {
    int skip = 0;
    int take = 0;

    for (int value : values) {
        int newTake = skip + value;
        int newSkip = Math.max(skip, take);
        take = newTake;
        skip = newSkip;
    }
    return Math.max(skip, take);
}

